use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, or None if the URL is not one we are
/// willing to request. Conservative: anything ambiguous is rejected so the
/// host never gets asked (a refused request would trap the whole run).
fn allowed_host(url: &str) -> Result<(), String> {
    let rest = if let Some(r) = url.strip_prefix("https://") {
        r
    } else if let Some(r) = url.strip_prefix("http://") {
        r
    } else {
        return Err("unsupported URL scheme".to_string());
    };
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty()
        || authority.contains('@')
        || authority.contains('\\')
        || authority.chars().any(|c| c.is_whitespace() || c.is_control())
    {
        return Err("malformed URL authority".to_string());
    }
    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if port.is_empty() || !port.chars().all(|c| c.is_ascii_digit()) {
                return Err("malformed URL port".to_string());
            }
            &authority[..i]
        }
        None => authority,
    };
    let host = host.to_ascii_lowercase();
    if ALLOWED_HOSTS.iter().any(|h| *h == host) {
        Ok(())
    } else {
        Err("host not in allowlist".to_string())
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if let Err(error) = allowed_host(&url) {
                failures.push(FetchFailure { url, error });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
